"""Library for Log Collection.

    = Configuration Needed =
    === testcase_variables ===
    | "*syslog_analysis*":{
    |	_*"analysis_name1"*_: {     User defined analysis name
    | 		*"eval"* : "",      Type of evaluation. Possible values: getCount, should_not_exist, should exist
    | 		*"regexp"* : ""     Regular Expression to be matched
    | 	},
    | }


    = Example =

    | ***** Test Cases *****
    | Capture and Analyse Syslog
    |		`Start Syslog`    /home/ute/IV_user     testSyslog.txt	alias=abc
    |		`Stop Syslog`
    |		`Analyse Syslog`		analysis=analysis_name1


    == Sample Configuration ==
    *Sample testcase_variables.json*
    | "syslog_analysis":{
    |	"analysis_name1": {
    |   	"eval":"getCount",
    |   	"regexp":["43FF-MOAM_ApwService"]
    |	},
    |	"analysis_name2": {
    |   	"eval":"should_not_exist",
    |   	"regexp":["abc"]
    |   },
    |   "analysis_name3": {
    |   	"eval":"should_exist",
    |   	"regexp":["43FF-MOAM_ApwService"]
    |   }
    | }

"""
from taf.ul.trs_e2e_fw.lib.utils.log_collection.emil_log import EmilLogOperations
from taf.ul.trs_e2e_fw.lib.utils.log_collection.syslog import SyslogOperations


def start_syslog(log_dir, log_name, ip='', ports=(51000, 51001, 51003, 50011), host_ip='127.0.0.1', file_limit=0,
                 add_line_number=False, alias='default', **kwargs):
    """
    _*Start Syslog*_  This Keyword is used to start collecting syslog

    *Usage*:
    Start Syslog <log_dir>  <log_name>  <ip>  <ports>  <host_ip> <file_limit> <add_line_number> <alias>



    | *Arguments* 		| *Comments* |   *Default Value* |
    | *log_dir* | Path to directory where syslog file should be stored. |
    | *log_name* | Name of file where collected data should be stored during collection. |
    | *ip* | Custom IP address where service should listen e.g. 192.168.255.126. By default all addresses and all
       interfaces (0.0.0.0/0). |
    | *ports* | Single or List of ports which will be used to collect syslog data. | (51000, 51001, 51003, 50011) |
    | *host_ip* | IP Address of remote/local machine | 127.0.0.1 |
    | *file_limit* | Size limit for the log file. Log file will be split into smaller parts if configured size is
       greater than 0. Size limit is specified in bytes | 0 |
    | *add_line_number* | Adds line numbers to the generated log file. | ${False} |
    | *alias* | Unique identifier for a certain syslog instance. | default |
    | *ssh_username* | Remote host user | ute |
    | *ssh_password* | Remote host password | ute |
    | *ssh_port* | Remote host port | 22 |
    | *ssh_prompt* | Remote host prompt | $ |

    *Example*
    | Start Syslog | /home/ute | syslog.txt |
    """
    return SyslogOperations.get_instance().start_syslog(log_dir, log_name, ip, ports, host_ip, file_limit,
                                                        add_line_number, alias, **kwargs)

                                
def stop_syslog(alias='default', **kwargs):
    """
    _*Stop Syslog*_  This Keyword is used to stop collecting syslog

    *Usage*:
    Stop Syslog <alias>

    | *Arguments* 		| *Comments* |    *Default Value* |
    | *alias* | Unique identifier for a certain syslog instance. | default |

    *Example*
    | Stop Syslog |
    """
    return SyslogOperations().get_instance().stop_syslog(alias, **kwargs)


def analyse_syslog(analysis, alias='default'):
    """

    _*Analyse Syslog*_  This keyword is used to parse and analyse captured syslog files.

    *Usage*:
    _Analyse Syslog <analysis>  <alias>_

    | *Arguments* 		| *Comments* |    *Default Value* |
    | *analysis* | Analysis section name in config file. |
    | *alias* | Unique identifier for a certain syslog instance. | default |

    *Examples*

    Analyse syslog file using the analysis "get_failure_message_count" defined in config file:
    | Analyse Syslog | get_failure_message_count |

    *Configurations Needed :*

    `testcase_variables` sections:

    "syslog_analysis"

    """
    return SyslogOperations.get_instance().analyse_syslog(analysis, alias)


def start_emil_log(**kwargs):
    """
    Start EMIL interface and capture syslog

    | *Arguments* | *Default Value* | *Comments* | *ref* |
    | sack_name | Mandatory |  |  |
    | emil_path | '/opt/Nokia/emil' |  |  |
    | host_ip | IP Address of remote/local machine | 127.0.0.1 |
    | test_name | 'test1' |  |  |
    | alias | Unique identifier for a certain syslog instance. | default |

    *Returns* \n
    list of log files

     *Examples*

    | Start Emil Log | sack_name=SBTS19_IDA_0000_000388_000023 |

    """
    return EmilLogOperations.get_instance().start_emil_log_capture(**kwargs)


def stop_emil_log(**kwargs):
    """
    Stops syslog capture and exits EMIL interface

    | *Arguments* | *Default Value* | *Comments* | *ref* |
    | sack_name | Mandatory |  |  |
    | emil_path | '/opt/Nokia/emil' |  |  |
    | host_ip | IP Address of remote/local machine | 127.0.0.1 |
    | test_name | 'test1' |  |  |
    | alias | Unique identifier for a certain syslog instance. | default |

    *Returns* \n
    None

     *Examples*

    | Stop Emil Log | sack_name=SBTS19_IDA_0000_000388_000023 |
    """
    return EmilLogOperations.get_instance().stop_emil_log_capture(**kwargs)


def execute_command_on_emil_interface(**kwargs):
    """
    Execute commands on EMIL interface

    | *Arguments* | *Default Value* | *Comments* | *ref* |
    | command | Mandatory |  |  |
    | exit_prompt | 'Emil>' | Exit prompt to be matched |  |
    | timeout | 30 | timeout for execution interface |  |
    | alias | Unique identifier for a certain syslog instance. | default |

    *Returns* \n
    Returns console output from EMIL interface

     *Examples*

    | Execute Command On Emil Interface | command=command_to_execute_on_emil_interface |
    """
    return EmilLogOperations.get_instance().execute_command_on_emil_interface(**kwargs)
